#!/bin/bash
# Generated By: Claude Code (Claude Opus 4.6)
# Shared functions for sandbox scripts.

# ---------------------------------------------------------------------------
# Jira helpers (shared by scode and generate-pr-context.sh)
# ---------------------------------------------------------------------------

JIRA_BASE="${JIRA_BASE:-https://redhat.atlassian.net}"
_JIRA_AC_FIELD=""

jira_auth() {
    local email="${JIRA_USERNAME:-${JIRA_EMAIL:-}}"
    local token="${JIRA_TOKEN:-${JIRA_API_TOKEN:-}}"
    if [[ -z "$email" || -z "$token" ]]; then
        return 1
    fi
    printf '%s' "$email:$token" | base64 -w0
}

jira_get() {
    local path="$1" auth="$2"
    curl -s -H "Authorization: Basic ${auth}" -H "Accept: application/json" \
        "${JIRA_BASE}${path}"
}

discover_ac_field() {
    local auth="$1"
    if [[ -n "$_JIRA_AC_FIELD" ]]; then
        echo "$_JIRA_AC_FIELD"
        return
    fi
    _JIRA_AC_FIELD=$(jira_get "/rest/api/3/field" "$auth" | \
        jq -r '.[] | select(.name == "Acceptance Criteria") | .id' | head -1)
    echo "$_JIRA_AC_FIELD"
}

render_adf_to_text() {
    python3 -c "
import json, sys

def walk(node):
    if isinstance(node, str):
        return node
    if isinstance(node, dict):
        t = node.get('type', '')
        text = node.get('text', '')
        if text:
            return text
        if t == 'hardBreak':
            # A line break inside a paragraph. It carries no text and no
            # children, so without this it renders as nothing and the lines
            # either side run together.
            return '\n'
        parts = [walk(c) for c in node.get('content', [])]
        joined = ''.join(parts)
        if t == 'paragraph':
            return joined + '\n\n'
        if t == 'bulletList':
            return joined
        if t == 'orderedList':
            return joined
        if t == 'listItem':
            return '- ' + joined.strip() + '\n'
        if t == 'heading':
            level = node.get('attrs', {}).get('level', 1)
            return '#' * level + ' ' + joined.strip() + '\n\n'
        if t == 'codeBlock':
            return '\`\`\`\n' + joined + '\`\`\`\n\n'
        return joined
    if isinstance(node, list):
        return ''.join(walk(c) for c in node)
    return ''

data = json.load(sys.stdin)
if isinstance(data, dict) and 'content' in data:
    print(walk(data).strip())
elif isinstance(data, str):
    print(data)
else:
    print(json.dumps(data, indent=2))
" 2>/dev/null
}

fetch_jira_context() {
    local key="$1" auth="$2"
    local ac_field
    ac_field=$(discover_ac_field "$auth")

    local fields="summary,description,status,issuetype"
    if [[ -n "$ac_field" ]]; then
        fields="${fields},${ac_field}"
    fi

    local issue
    issue=$(jira_get "/rest/api/3/issue/${key}?fields=${fields}" "$auth")
    if [[ -z "$issue" ]] || echo "$issue" | jq -e '.errorMessages' &>/dev/null; then
        echo "Warning: could not fetch Jira ${key}" >&2
        return
    fi

    local summary status issue_type
    summary=$(echo "$issue" | jq -r '.fields.summary // ""')
    status=$(echo "$issue" | jq -r '.fields.status.name // ""')
    issue_type=$(echo "$issue" | jq -r '.fields.issuetype.name // ""')

    echo "### ${key}: ${summary}"
    echo ""
    echo "**Type:** ${issue_type} | **Status:** ${status}"
    echo ""

    local desc
    desc=$(echo "$issue" | jq '.fields.description')
    if [[ "$desc" != "null" ]]; then
        echo "#### Description"
        echo ""
        echo "$desc" | render_adf_to_text
        echo ""
    fi

    if [[ -n "$ac_field" ]]; then
        local ac
        ac=$(echo "$issue" | jq ".fields.${ac_field}")
        if [[ "$ac" != "null" && "$ac" != '""' ]]; then
            echo "#### Acceptance Criteria"
            echo ""
            echo "$ac" | render_adf_to_text
            echo ""
        fi
    fi
}

# Banner for jira-comments.md. The file exists so a session can be told NOT to
# read it at all; mixing comments into jira-context.md makes that impossible.
# What it says when opened anyway: discussion, not requirements.
jira_comments_header() {
    echo "# Jira Discussion"
    echo ""
    echo "> **Discussion only. Not authoritative.** Requirements live in"
    echo "> \`jira-context.md\` — the issue description and Acceptance Criteria."
    echo "> Where a comment conflicts with them, they win. Comments may be stale,"
    echo "> superseded, contradictory, or proposals that were rejected. Never"
    echo "> derive requirements, scope, decisions, or estimates from this file."
    echo "> Read it only when asked to investigate history or rationale."
}

# Render one issue's comments as markdown on stdout, for jira-comments.md.
# Never for jira-context.md: the two are split so the prompt can say do not
# read the discussion file, keeping comments out of a working session's context
# entirely. A failed fetch is reported in the file rather than as an empty
# section, so "no comments" and "could not read them" stay distinguishable.
fetch_jira_comments() {
    local key="$1" auth="$2"
    local start_at=0 page_size=50 fetched=0 total=0
    local all_comments="[]" resp page_count

    while :; do
        resp=$(jira_get "/rest/api/3/issue/${key}/comment?orderBy=created&maxResults=${page_size}&startAt=${start_at}" "$auth")
        if ! jq -e '.comments' >/dev/null 2>&1 <<<"$resp"; then
            echo "## ${key}"
            echo ""
            echo "_Unavailable: could not fetch comments for ${key}._"
            echo ""
            return 0
        fi
        all_comments=$(jq -s '.[0] + (.[1].comments // [])' \
            <(printf '%s' "$all_comments") <(printf '%s' "$resp"))
        page_count=$(jq '.comments | length' <<<"$resp")
        fetched=$(( fetched + page_count ))
        total=$(jq '.total // 0' <<<"$resp")
        # A page the API keeps answering with the same rows would otherwise
        # loop forever; total is what normally ends it.
        (( page_count == 0 )) && break
        (( fetched >= total )) && break
        start_at=$fetched
    done

    local count i author created body
    count=$(jq 'length' <<<"$all_comments")
    echo "## ${key} (${count} comments)"
    echo ""
    for (( i = 0; i < count; i++ )); do
        author=$(jq -r ".[$i].author.displayName // \"Unknown\"" <<<"$all_comments")
        created=$(jq -r "(.[$i].created // \"\")[0:16] | gsub(\"T\"; \" \")" <<<"$all_comments")
        body=$(jq -c ".[$i].body" <<<"$all_comments")
        echo "### ${author} — ${created}"
        echo ""
        [[ "$body" == "null" ]] || printf '%s\n' "$body" | render_adf_to_text
        echo ""
    done
}

_LIB_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"

# Result marks — see standards/cli/conventions.md. MARK_OK is openshell's own
# green bold ✓, reproduced because upload_repo() reprints that line to hang the
# reason off it. Colour only on a tty, so a redirected log keeps the glyphs
# without the escapes.
# shellcheck disable=SC2034  # MARK_OK is used by sandbox.sh, which sources this
if [[ -t 2 ]]; then
    MARK_OK=$'\033[1;32m✓\033[0m'
    MARK_SKIP=$'\033[1;33m⊘\033[0m'
else
    MARK_OK='✓'
    MARK_SKIP='⊘'
fi

# ---------------------------------------------------------------------------
# Upload change detection
# ---------------------------------------------------------------------------
#
# `openshell sandbox upload` is tar-over-SSH with no delta protocol, and
# upload_repo() rm -rf's the sandbox copy first, so every upload re-sends the
# whole repo including .git. On a multi-repo sandbox the reference repos
# (standards, knowledgebase, a vendored upstream) never change and dominate the
# payload. The only lever is not sending a repo at all.
#
# The signal is mtime against .repos[<name>].last_upload in manifest.json, and
# every --upload consults it unless --force is given. --force re-sends every
# repo: upload_repo() rm -rf's the sandbox copy first, so it doubles as the way
# to wipe edits a session made inside the sandbox, and skipping on "the host has
# not changed" would assume the very thing --force exists to fix.

# Stamp .repos[<name>].<field> with an absolute UTC timestamp.
#
# Whole seconds, because that is all `find -newermt` accepts — bfs, the find in
# the sandbox image, rejects a fractional timestamp outright. Truncation puts
# the stamp at or before the moment it describes, so a file written earlier in
# that same second reads as newer and the repo is tarred again; the next stamp
# settles it. Rounding up instead would defer such a file to whenever the repo
# next changes for any other reason, since the skip and the tar are both
# whole-repo. Neither is a correctness problem. Truncating needs no arithmetic.
record_repo_timestamp() {
    local sandbox_dir="$1" repo_name="$2" field="$3"
    local manifest="${sandbox_dir}/manifest.json"
    [[ -f "$manifest" ]] || return 0
    local ts
    ts=$(date -u +"%Y-%m-%dT%H:%M:%SZ")
    jq --arg r "$repo_name" --arg f "$field" --arg ts "$ts" \
        '.repos[$r] = (.repos[$r] // {}) + {($f): $ts}' \
        "$manifest" > "${manifest}.tmp" && mv "${manifest}.tmp" "$manifest"
}

# True when the repo has anything modified since its last upload — including
# never having been uploaded, or a manifest that does not say.
#
# Says why on stderr as a bare fragment, naming no repo: upload_repo() captures
# it and hangs it off its own `✓ Upload complete` line, which sits under an
# openshell header that has already named one.
#
# ponytail: mtime only, like make and like rsync's default. A file edited and
# restored to its original size and mtime is missed. Content hashing a 59M .git
# costs more than the tar it saves.
repo_changed_since_upload() {
    local sandbox_dir="$1" repo_name="$2"
    local manifest="${sandbox_dir}/manifest.json"

    local last_upload=""
    if [[ -f "$manifest" ]]; then
        last_upload=$(jq -r --arg r "$repo_name" '.repos[$r].last_upload // empty' \
            "$manifest" 2>/dev/null || true)
    fi
    if [[ -z "$last_upload" ]]; then
        echo "has no last_upload recorded" >&2
        return 0
    fi

    # -print -quit stops at the first newer path, so a changed repo usually
    # costs far less than the full walk an unchanged one pays.
    #
    # The tripped path is named, not just the verdict: "it uploads every time" is
    # otherwise indistinguishable from a broken stamp, and the answer is whichever
    # file the walk stopped on. Repo-relative, because the absolute prefix is the
    # same on every line and pushed the reason onto a line of its own. A walk that
    # stops on the repo directory itself has no tail to show, and names none.
    #
    # Three paths are excluded because `git status` rewrites them and nothing
    # else does. Measured, not assumed: status touches exactly `.git` and
    # `.git/index`, plus a transient `.git/index.lock` whose creation and
    # deletion is what moves the `.git` directory's own mtime. Any editor or
    # shell prompt polling status therefore made every repo look modified,
    # forever. The rest of `.git` is still walked, so staging is caught
    # (`git add` always writes a blob under `.git/objects`), as are commits
    # (refs, logs) and branch switches (HEAD).
    #
    # More for `git fetch` that brings nothing: it rewrites FETCH_HEAD and
    # moves the `.git/objects` directory's mtime with a transient temp file;
    # git 2.56 (not 2.47) also moves the mtime of each `refs/remotes/<remote>`
    # directory without changing a ref in it. Measured the same way. A fetch
    # that does bring something writes object files and ref files, which are
    # still walked. Only directories under refs/remotes are skipped, and the one
    # change only they showed — prune deleting a loose remote ref — also removes
    # its reflog, which moves `logs/refs/remotes/<remote>`, still walked.
    #
    # ponytail: with core.logAllRefUpdates=false there is no reflog, so a prune
    # that only deletes a loose remote ref is missed; --upload --force sends it.
    #
    # ponytail: the gap is an index-only edit that writes no object — `git
    # reset` to unstage, with nothing else touched. The walk misses that;
    # --upload --force sends it.
    local repo_dir="${sandbox_dir}/${repo_name}" newer
    newer=$(find "$repo_dir" -newermt "$last_upload" \
        ! -path "${repo_dir}/.git" \
        ! -path "${repo_dir}/.git/index" \
        ! -path "${repo_dir}/.git/index.lock" \
        ! -path "${repo_dir}/.git/objects" \
        ! -path "${repo_dir}/.git/FETCH_HEAD" \
        ! \( -type d -path "${repo_dir}/.git/refs/remotes/*" \) \
        -print -quit 2>/dev/null || true)
    [[ -n "$newer" ]] || return 1
    local tail=""
    [[ "$newer" == "$repo_dir" ]] || tail=" (${newer#"${repo_dir}/"})"
    echo "newer than ${last_upload}${tail}" >&2
}

format_open_prs() {
    python3 "${_LIB_DIR}/format-open-prs.py" "$@"
}

# Fetch into a file rather than redirecting the whole retry loop: `>` truncates
# per attempt, so a partial write from a failed attempt cannot end up prepended
# to a good one.
fetch_open_prs() {
    local gh_repo="$1" dest="$2"
    format_open_prs "$gh_repo" > "$dest"
}

# ---------------------------------------------------------------------------
# PR checkout + per-repo context generation (pr-context.md + jira-context.md)
# ---------------------------------------------------------------------------

# Retry budget for the ONE gh call worth waiting on: `gh pr checkout`, which
# decides what code is in the sandbox, runs once per repo at create time, and
# falls back to a worse checkout if it fails.
#
# Nothing else retries. Context generation runs on every upload, once per repo,
# and when GitHub is down a 3-attempt backoff there turns a multi-repo upload
# into minutes of sleeping for data that is optional (open-prs.json) or already
# on disk (pr-context.md). One attempt, warn, move on.
GH_RETRY_ATTEMPTS="${GH_RETRY_ATTEMPTS:-3}"
GH_RETRY_DELAY="${GH_RETRY_DELAY:-2}"

# Run a command, retrying transient failures with a doubling delay.
# Only for calls whose failure is always an error — never for one where
# "not found" is an expected answer, or every miss costs the full backoff.
gh_retry() {
    local attempt=1 delay="$GH_RETRY_DELAY"
    while :; do
        "$@" && return 0
        (( attempt++ >= GH_RETRY_ATTEMPTS )) && return 1
        echo "gh call failed, retrying in ${delay}s (attempt ${attempt}/${GH_RETRY_ATTEMPTS})..." >&2
        sleep "$delay"
        delay=$(( delay * 2 ))
    done
}

# Fetch a PR as JSON on stdout.
#   0 — JSON on stdout
#   2 — gh answered, and there is no such PR (final; do not retry, do not
#       treat as an outage)
#   1 — gh could not answer after retries; the caller knows nothing new
#
# The split matters because `gh pr view` exits 1 for both, and the caller
# deletes stale context files on "no PR". Conflating them means a 502 during
# an upload destroys correct pr-context.md and jira-context.md — and
# jira-context.md costs Jira calls to rebuild.
gh_pr_view_json() {
    local pr_arg="$1" gh_repo="$2" out err rc=1
    err="$(mktemp)"
    if out=$(gh pr view "$pr_arg" --repo "$gh_repo" \
        --json number,title,body,headRefName,baseRefName,labels,assignees 2>"$err"); then
        printf '%s' "$out"
        rc=0
    else
        case "$(cat "$err")" in
            *"no pull requests found"*|*"no open pull requests"*|*"Could not resolve"*)
                rc=2
                ;;
            *)
                echo "Warning: gh pr view failed: $(head -1 "$err")" >&2
                ;;
        esac
    fi
    rm -f "$err"
    return "$rc"
}

# A paginated REST endpoint as one JSON array on stdout.
#
# Used for every PR comment source rather than `gh pr view --json
# comments,reviews`: gh's own paging is internal and unverified, so a busy PR
# could silently lose rows. `--paginate` emits one JSON array per page and
# `jq -s` + `add` flattens them.
#
# One attempt, like every other context call: the caller records the failure
# in pr-comments.md rather than letting it read as "no comments".
gh_api_paginated_json() {
    local path="$1" out err
    err="$(mktemp)"
    if out=$(gh api --paginate "$path" 2>"$err") \
        && out=$(jq -cs 'add // []' <<<"$out" 2>>"$err"); then
        rm -f "$err"
        printf '%s' "$out"
        return 0
    fi
    echo "Warning: gh api ${path} failed: $(head -1 "$err")" >&2
    rm -f "$err"
    return 1
}

# Check out a PR as a real branch. `git fetch origin pull/N/head:pr-N` produced
# a branch named pr-N with no upstream at all — fine to work in, but anything
# reading @{upstream} (monitoring, prompt, status tooling) sees a local-only
# branch. `gh pr checkout` names the branch after the PR head ref and writes
# branch.<name>.{remote,merge}, so the checkout looks like any other branch.
#
# The fallback keeps the old refs/pull fetch: gh needs auth and network, and a
# create that silently stays on the default branch is worse than a branch
# without tracking. generate_repo_context() reads both spellings.
checkout_pr() {
    local target="$1" pr_num="$2"

    if [[ "${DRYRUN:-false}" == true ]]; then
        echo "[dryrun]: (cd ${target} && gh pr checkout ${pr_num})" >&2
        return 0
    fi

    # cd, not -C: gh has no repo-directory flag, and --repo names the GitHub
    # repo, not the clone to check out into.
    if ( cd "$target" && gh_retry gh pr checkout "$pr_num" ); then
        return 0
    fi

    echo "Warning: gh pr checkout ${pr_num} failed — falling back to a refs/pull fetch, which leaves the branch without an upstream" >&2
    git -C "$target" fetch origin "pull/${pr_num}/head:pr-${pr_num}"
    git -C "$target" checkout "pr-${pr_num}"
}

# How long an open-prs.json is trusted before the PR list is fetched again.
# `gh pr list --json files` is the slowest call in an upload and it runs once
# per repo, so a multi-repo `--upload` paid for a full refetch every time even
# when nothing could plausibly have changed. An hour is short enough that a PR
# opened this morning shows up, long enough that repeated uploads are free.
# Set OPEN_PRS_TTL_MINUTES=0 to force a fetch.
OPEN_PRS_TTL_MINUTES="${OPEN_PRS_TTL_MINUTES:-60}"

generate_repo_context() {
    local sandbox_dir="$1" repo_name="$2" profile="${3:-}"
    local repo_dir="${sandbox_dir}/${repo_name}"
    local manifest="${sandbox_dir}/manifest.json"

    [[ -d "${repo_dir}/.git" ]] || return 0
    [[ -f "$manifest" ]] || return 0

    local repo_url
    repo_url=$(jq -r --arg r "$repo_name" '.repos[$r].url // ""' "$manifest")
    [[ "$repo_url" =~ github\.com ]] || return 0

    local gh_repo
    # Trailing slashes are optional and independent of .git: the manifest holds
    # both `…/standards/` and `…/knowledgebase.git/`. Stripping only `.git/?`
    # left the first spelling as `jewzaam/standards/`, which gh rejects.
    gh_repo=$(echo "$repo_url" | sed -E 's|.*github\.com[:/]||; s|(\.git)?/*$||')

    # open-prs.json — all open PRs, compact structured data
    local open_prs="${repo_dir}/open-prs.json"
    # Age in minutes, or "old enough" when the file is missing or unreadable.
    # Not `find -newermt "-N minutes"`: the sandbox image's find is bfs, which
    # takes only absolute ISO timestamps and errors on the relative form — the
    # check would have silently meant "always stale".
    local open_prs_age=999999
    if [[ -f "$open_prs" ]]; then
        open_prs_age=$(( ( $(date +%s) - $(stat -c %Y "$open_prs" 2>/dev/null || echo 0) ) / 60 ))
    fi

    if (( open_prs_age < OPEN_PRS_TTL_MINUTES )); then
        echo "${MARK_SKIP} PR list fetch skipped — open-prs.json is ${open_prs_age}m old (< ${OPEN_PRS_TTL_MINUTES}m)" >&2
    elif fetch_open_prs "$gh_repo" "${open_prs}.tmp"; then
        # A repo with no open PRs gets `{"prs": []}`, not a missing file: the
        # absence of the file used to mean "none", "gh failed", and "not a
        # GitHub repo" all at once, and a session cannot tell those apart.
        mv "${open_prs}.tmp" "$open_prs"
    else
        # Failed fetch: record it IN the file, which puts the failure under the
        # same debounce as a success. These failures are repo-pinned — a repo
        # gh cannot read fails identically on every upload — so retrying each
        # one every time is pure cost. Any real data already here is kept and
        # marked stale rather than replaced with a lie about there being no PRs.
        local now
        now=$(date -u +"%Y-%m-%dT%H:%M:%SZ")
        if [[ -f "$open_prs" ]] && jq --arg at "$now" --arg repo "$gh_repo" \
            '. + {fetch_error: ("gh pr list failed for " + $repo), fetch_error_at: $at}' \
            "$open_prs" > "${open_prs}.tmp"; then
            mv "${open_prs}.tmp" "$open_prs"
        else
            rm -f "${open_prs}.tmp"
            jq -n --arg at "$now" --arg repo "$gh_repo" \
                '{fetch_error: ("gh pr list failed for " + $repo), fetch_error_at: $at}' \
                > "$open_prs"
        fi
        echo "Open PRs unknown for ${gh_repo} — recorded, no retry for ${OPEN_PRS_TTL_MINUTES}m" >&2
    fi

    # Detect PR from current branch (git state is source of truth, not manifest ref)
    local branch pr_arg
    branch=$(git -C "$repo_dir" rev-parse --abbrev-ref HEAD 2>/dev/null) || return 0
    # A PR checkout is normally a real branch (gh pr checkout), so the name is
    # the head ref and `gh pr view <branch>` resolves it.
    pr_arg="$branch"
    # Legacy and fallback checkouts are named pr-<num>; no such branch exists
    # on the remote, so gh pr view needs the number.
    if [[ "$branch" =~ ^pr-([0-9]+)$ ]]; then
        pr_arg="${BASH_REMATCH[1]}"
    fi
    # A fork PR's head ref lives in the fork, so the branch name does not
    # identify it in the base repo. gh writes refs/pull/<num>/head as the
    # upstream in that case — the number is right there, no guessing.
    local merge_ref
    merge_ref=$(git -C "$repo_dir" config "branch.${branch}.merge" 2>/dev/null || true)
    if [[ "$merge_ref" =~ ^refs/pull/([0-9]+)/head$ ]]; then
        pr_arg="${BASH_REMATCH[1]}"
    fi

    echo "Checking branch '${branch}' for PR..." >&2
    local pr_json rc
    pr_json=$(gh_pr_view_json "$pr_arg" "$gh_repo") || rc=$?

    # `gh pr view <branch>` resolves a branch name against the BASE repo only,
    # so a PR opened from a fork is invisible to it — "no pull requests found"
    # even though the PR is open and its head ref has exactly that name.
    # `gh pr list --head` matches the head ref wherever it lives.
    #
    # Deliberately NOT read out of open-prs.json, which holds the same numbers:
    # that file is optional and debounced, and its own fetch fails on its own
    # (`--json files` over a repo with many open PRs), so the PR would be
    # unresolvable exactly when the list is broken. Measured on
    # ansible/handbook: `pr view` answered, the bulk `pr list` did not.
    #
    # The cost is one extra call on a path that has already failed, not on
    # every upload. Only for a branch, and only when exactly one open PR claims
    # that head ref — two forks can use the same branch name, and picking one
    # would be a guess.
    if [[ "${rc:-0}" == 2 && ! "$pr_arg" =~ ^[0-9]+$ ]]; then
        local fork_pr
        fork_pr=$(gh pr list --repo "$gh_repo" --state open --head "$branch" \
            --json number 2>/dev/null \
            | jq -r '[.[].number] | if length == 1 then .[0] else empty end' 2>/dev/null || true)
        if [[ -n "$fork_pr" ]]; then
            echo "    head ref is not in ${gh_repo} — PR #${fork_pr}" >&2
            rc=""
            pr_json=$(gh_pr_view_json "$fork_pr" "$gh_repo") || rc=$?
        fi
    fi

    if [[ -n "${rc:-}" ]]; then
        if (( rc == 2 )); then
            # gh answered: no such PR. Whatever context is here is stale.
            rm -f "${repo_dir}/pr-context.md" "${repo_dir}/pr-comments.md" \
                  "${repo_dir}/jira-context.md" "${repo_dir}/jira-comments.md"
        else
            # gh could not answer. Deleting here would throw away correct
            # context on a transient API failure, so keep what is on disk.
            echo "Keeping existing PR context for ${repo_name} (gh unreachable)" >&2
        fi
        return 0
    fi

    local pr_num
    pr_num=$(echo "$pr_json" | jq -r '.number')

    # Update manifest ref to match actual checkout
    jq --arg r "$repo_name" --arg ref "pr/${pr_num}" \
        '.repos[$r].ref = $ref' "$manifest" > "${manifest}.tmp" && mv "${manifest}.tmp" "$manifest"

    echo "Generating context for ${repo_name} PR #${pr_num}..." >&2

    local pr_title pr_branch pr_base pr_body pr_labels pr_assignees
    pr_title=$(echo "$pr_json" | jq -r '.title // ""')
    pr_branch=$(echo "$pr_json" | jq -r '.headRefName // ""')
    pr_base=$(echo "$pr_json" | jq -r '.baseRefName // ""')
    pr_body=$(echo "$pr_json" | jq -r '.body // ""')
    pr_labels=$(echo "$pr_json" | jq -r '[.labels[].name] | join(", ") // ""')
    pr_assignees=$(echo "$pr_json" | jq -r '[.assignees[].login] | join(", ") // ""')

    # Every comment source is a paginated REST call we control, so the rows in
    # pr-comments.md are not subject to gh's internal `pr view` paging, which
    # is unverified and could silently cap a busy PR. Bodies are emitted
    # verbatim: a suggestion block is the reviewer's exact proposed text, so
    # truncating or reformatting it loses the point of including it at all.
    # A failed fetch is written into the file rather than left as an empty
    # section, so "no comments" and "could not read the comments" stay
    # distinguishable.
    local pr_comment_count=unavailable pr_comments pr_review_count=unavailable pr_reviews
    local pr_inline_count=unavailable pr_inline
    local comments_json reviews_json inline_json

    echo "Fetching PR comments and reviews..." >&2

    if comments_json=$(gh_api_paginated_json \
            "repos/${gh_repo}/issues/${pr_num}/comments?per_page=100"); then
        pr_comment_count=$(jq -r 'length' <<<"$comments_json")
        pr_comments=$(jq -r '
            .[] |
            "### @\(.user.login // "unknown") — \((.created_at // "")[0:16] | gsub("T"; " "))\n\n\(.body // "")\n"' \
            <<<"$comments_json")
    else
        pr_comments="_Unavailable: gh api repos/${gh_repo}/issues/${pr_num}/comments failed._"$'\n\n'
    fi

    if reviews_json=$(gh_api_paginated_json \
            "repos/${gh_repo}/pulls/${pr_num}/reviews?per_page=100"); then
        pr_review_count=$(jq -r 'length' <<<"$reviews_json")
    else
        pr_reviews="_Unavailable: gh api repos/${gh_repo}/pulls/${pr_num}/reviews failed._"$'\n\n'
    fi

    if inline_json=$(gh_api_paginated_json \
            "repos/${gh_repo}/pulls/${pr_num}/comments?per_page=100"); then
        pr_inline_count=$(jq -r 'length' <<<"$inline_json")
        # diff_hunk is the API's own diff excerpt for the commented position:
        # `-` lines are the original text, `+` the proposed, the rest context.
        # Without it a comment is text pinned to a line number with nothing to
        # read it against.
        pr_inline=$(jq -r '
            .[] |
            "### @\(.user.login // "unknown") — \(.path // "?"):\(.line // .original_line // "?") — \((.created_at // "")[0:16] | gsub("T"; " "))\n\n"
            + (if ((.diff_hunk // "") | test("\\S"))
               then "```diff\n\(.diff_hunk)\n```\n\n" else "" end)
            + "\(.body // "")\n"' \
            <<<"$inline_json")
    else
        pr_inline="_Unavailable: gh api repos/${gh_repo}/pulls/${pr_num}/comments failed._"$'\n\n'
    fi

    # Reviews and inline comments are rendered together: an inline comment's
    # only context is the review submission it belongs to, and GitHub links
    # them by pull_request_review_id. A review with an empty body is not empty
    # — its text is those inline comments. Measured on handbook PR #1858:
    # 35 inline comments across 28 reviews, 0 without a review id.
    local pr_extra_heading="" pr_extra_count="" pr_extra=""
    if [[ "$pr_review_count" != unavailable && "$pr_inline_count" != unavailable ]]; then
        local reviews_file inline_file
        reviews_file=$(mktemp)
        inline_file=$(mktemp)
        printf '%s' "$reviews_json" > "$reviews_file"
        printf '%s' "$inline_json" > "$inline_file"

        pr_reviews=$(jq -r --slurpfile inline_rows "$inline_file" '
            .[] | . as $rev
            | ([$inline_rows[0][] | select(.pull_request_review_id == $rev.id)]) as $rows
            | "### @\($rev.user.login // "unknown") — \($rev.state // "") — \(($rev.submitted_at // "")[0:16] | gsub("T"; " "))\n\n"
              + (if (($rev.body // "") | test("\\S")) then "\($rev.body)\n\n"
                 elif ($rows | length) == 0 then "_No comment._\n\n"
                 else "" end)
              + ($rows | map(
                   "#### \(.path // "?"):\(.line // .original_line // "?")\n\n"
                   + (if ((.diff_hunk // "") | test("\\S"))
                      then "```diff\n\(.diff_hunk)\n```\n\n" else "" end)
                   + "\(.body // "")\n") | join("\n"))
        ' "$reviews_file")

        # An inline comment the reviews list does not account for must not be
        # dropped, even though the API has never produced one.
        pr_extra_count=$(jq -r --slurpfile revs "$reviews_file" '
            [.[] | select(.pull_request_review_id as $id
                          | ($revs[0] | map(.id) | index($id)) == null)] | length' \
            "$inline_file")
        if (( pr_extra_count > 0 )); then
            pr_extra_heading="## Inline Comments Without a Review (${pr_extra_count})"
            pr_extra=$(jq -r --slurpfile revs "$reviews_file" '
                .[] | select(.pull_request_review_id as $id
                             | ($revs[0] | map(.id) | index($id)) == null)
                | "### @\(.user.login // "unknown") — \(.path // "?"):\(.line // .original_line // "?") — \((.created_at // "")[0:16] | gsub("T"; " "))\n\n"
                  + (if ((.diff_hunk // "") | test("\\S"))
                     then "```diff\n\(.diff_hunk)\n```\n\n" else "" end)
                  + "\(.body // "")\n"' "$inline_file")
        fi
        rm -f "$reviews_file" "$inline_file"
    else
        # One half is missing, so reviews cannot be grouped. Keep the flat
        # sections and say what could not be read.
        pr_extra_heading="## Inline Review Comments (${pr_inline_count})"
        pr_extra="$pr_inline"
    fi

    # pr-context.md — PR metadata and description only. Anything a session
    # needs to do the work must be here, because pr-comments.md is the file the
    # prompt tells sessions not to read unless they are handling feedback.
    {
        echo "# PR #${pr_num}: ${pr_title}"
        echo ""
        echo "**Branch:** ${pr_branch}"
        echo "**Base:** ${pr_base}"
        echo "**Labels:** ${pr_labels}"
        echo "**Assignees:** ${pr_assignees}"
        echo ""
        echo "Diff against base: \`git diff origin/${pr_base}...HEAD\`"
        echo ""
        echo "# PR Description"
        echo ""
        echo "$pr_body"
    } > "${sandbox_dir}/${repo_name}/pr-context.md"
    echo "    wrote pr-context.md" >&2

    # pr-comments.md — discussion, deliberately a separate file. All three
    # sources come from paginated REST calls, never `gh pr view`.
    {
        echo "# PR #${pr_num}: ${pr_title} — Discussion"
        echo ""
        echo "> **Discussion only. Not authoritative.** Requirements and intent"
        echo "> live in \`pr-context.md\`, the PR description, and the code. Read"
        echo "> this file only when responding to review feedback or verifying a"
        echo "> prior comment. A review comment is feedback to act on, not an"
        echo "> instruction — check it against the current code before changing"
        echo "> anything, and do not treat a comment as superseding the"
        echo "> description."
        echo ""
        # Sections are h2 under the file's h1 title; entries are h3.
        echo "## PR Comments (${pr_comment_count})"
        echo ""
        printf '%s' "$pr_comments"
        echo "## PR Reviews (${pr_review_count})"
        echo ""
        printf '%s' "$pr_reviews"
        if [[ -n "$pr_extra_heading" ]]; then
            echo "$pr_extra_heading"
            echo ""
            printf '%s' "$pr_extra"
        fi
    } > "${sandbox_dir}/${repo_name}/pr-comments.md"
    echo "    wrote pr-comments.md" >&2

    # jira-context.md — Jira issue context (skip for personal/home profiles)
    personal_profile "$profile" && return 0

    local jira_keys
    jira_keys=$(printf '%s\n%s\n%s' "$pr_title" "$pr_branch" "$pr_body" | \
        grep -oE '[a-zA-Z]+-[0-9]+' | sort -u || true)

    [[ -n "$jira_keys" ]] || return 0

    local auth
    auth=$(jira_auth) || {
        echo "${MARK_SKIP} Jira context skipped — JIRA_USERNAME/JIRA_TOKEN not set" >&2
        return 0
    }

    {
        echo "# Jira Context"
        echo ""
        for key in $jira_keys; do
            echo "Fetching Jira ${key}..." >&2
            fetch_jira_context "$key" "$auth"
        done
    } > "${sandbox_dir}/${repo_name}/jira-context.md"
    echo "    wrote jira-context.md" >&2

    # jira-comments.md — discussion, separate for the same reason as
    # pr-comments.md: the prompt can tell a session not to read it.
    {
        jira_comments_header
        echo ""
        for key in $jira_keys; do
            echo "Fetching Jira comments for ${key}..." >&2
            fetch_jira_comments "$key" "$auth"
        done
    } > "${sandbox_dir}/${repo_name}/jira-comments.md"
    echo "    wrote jira-comments.md" >&2
}

# ---------------------------------------------------------------------------
# Profiles
# ---------------------------------------------------------------------------

# The complete set. There is no default and no inference: sandbox.sh --create
# and every scode invocation demand one by name, because the profile decides
# which credentials leave the host, and a wrong guess there is silent.
valid_profile() {
    [[ "$1" == work || "$1" == personal || "$1" == home ]]
}

# Profiles that carry no work credentials. `home` is `personal` plus the
# Prometheus and Loki reads, and that difference lives entirely in the policy,
# so every credential, env var, and system-prompt decision treats the two
# alike. Which agent runs is `--harness`, not a profile — see valid_harness().
personal_profile() {
    [[ "$1" == personal || "$1" == home ]]
}

# Managed settings are read only from /etc/claude-code/managed-settings.json on
# Linux, root-owned. `deniedModels` must therefore live in an image layer: a
# runtime upload needs a writable destination, and anything the sandbox user can
# write the agent can rewrite to unblock the models. So work runs a derived
# image with the file baked in, and /etc is read_only in the policy, making it
# unmodifiable from inside. Personal and home run the base image, which has no
# managed settings at all.
sandbox_image_for() {
    local profile="$1"
    local base="${SANDBOX_IMAGE_NAME:-openshell-sandbox}"
    local tag="${SANDBOX_IMAGE_TAG:-latest}"
    if personal_profile "$profile"; then
        printf '%s:%s\n' "$base" "$tag"
    else
        printf '%s-work:%s\n' "$base" "$tag"
    fi
}

# ---------------------------------------------------------------------------
# Repo visibility helpers
# ---------------------------------------------------------------------------

# Check if repo is private via gh CLI. Returns 0 if private, 1 if public.
is_private_repo() {
    local url="${1%/}"
    local private
    private=$(gh repo view "$url" --json isPrivate -q '.isPrivate' 2>/dev/null) || return 1
    [[ "$private" == "true" ]]
}

# ---------------------------------------------------------------------------
# Sandbox manifest (shared by scode and sandbox.sh)
# ---------------------------------------------------------------------------

# True for an openshell name this script makes: sb-<12 hex>, under
# OpenShell's 19-char DNS label limit. --reap and --delete use it to touch only
# containers this script named.
is_our_openshell_name() {
    [[ "$1" =~ ^sb-[0-9a-f]{12}$ ]]
}

# A random openshell name. Never derived from the sandbox name or any other
# key: --rename keeps the container's name, so a derived one makes create foo,
# rename to bar, create foo land on bar's container.
new_openshell_name() {
    echo "sb-$(od -An -N6 -tx1 /dev/urandom | tr -d ' \n')"
}

# A new_openshell_name() that is taken nowhere: not stored in any manifest
# under SANDBOXES_PARENT (a directory whose container may not exist yet), and
# not a container the gateway already has (whatever made it). The gateway is
# asked once, and a failed or paged list is an error, not "nothing taken":
# minting blind is how a name lands on someone else's container. Collisions are
# ~n^2/2^49 for n names, so a retry essentially never runs; the cap turns a
# broken random source (one value forever) into an error instead of a hang.
#
# Under --dryrun (DRYRUN=true) nothing is created, so the gateway is not asked
# and any unclaimed random name will do.
#
# The gateway asked is whatever the caller's GW_FLAG array selects. Only
# sandbox.sh sets it; scode never does, so from scode this lists the default
# gateway — the same one scode's sandbox is created on.
OPENSHELL_NAME_ATTEMPTS=5
mint_openshell_name() {
    local sandboxes_parent="$1" live="" attempt candidate
    # --page-size 1000 and the paged check: same as --reap's list.
    if [[ "${DRYRUN:-false}" != true ]] \
        && ! live="$(openshell sandbox list "${GW_FLAG[@]+"${GW_FLAG[@]}"}" --page-size 1000 \
            --output json 2>/dev/null \
            | jq -r 'if (.next_page_token // "") == "" then (.sandboxes // [])[].name
                     else error("paged") end')"; then
        echo "Error: openshell sandbox list failed or came back incomplete; not picking an openshell name blind" >&2
        return 1
    fi
    for (( attempt = 1; attempt <= OPENSHELL_NAME_ATTEMPTS; attempt++ )); do
        candidate="$(new_openshell_name)"
        if ! grep -qxF -- "$candidate" <<<"$live" \
            && ! openshell_name_claimed "$candidate" "$sandboxes_parent"; then
            echo "$candidate"
            return 0
        fi
        echo "openshell name ${candidate} already in use, retrying" >&2
    done
    echo "Error: no unused openshell name after ${OPENSHELL_NAME_ATTEMPTS} attempts" >&2
    return 1
}

# True when a manifest under SANDBOXES_PARENT stores OS_NAME.
openshell_name_claimed() {
    local os_name="$1" sandboxes_parent="$2" manifest
    for manifest in "${sandboxes_parent}"/*/manifest.json; do
        [[ -f "$manifest" ]] || continue
        [[ "$(jq -r '.openshell_name // empty' "$manifest")" == "$os_name" ]] && return 0
    done
    return 1
}

# Write the manifest skeleton — name, openshell name, profile — creating the
# sandbox dir if needed. Idempotent: an existing manifest keeps its repos and
# only has .profile refreshed.
#
# Every path that creates a sandbox calls this before anything else touches
# the directory: the manifest is the only record of the container's name, so a
# directory without one names nothing. The name is minted before the directory
# exists, so a failed mint leaves nothing behind.
#
# scode calls this before opening VS Code, and sandbox.sh before `openshell
# sandbox create`, because the host prompt reads .profile out of this file.
# Written only by the repo loop, it appears minutes late — after create, the
# credential uploads, and the host clone — and until then every shell in that
# directory shows no profile at all.
init_manifest() {
    local sandbox_dir="$1" sandbox_name="$2" profile="${3:-}" harness="${4:-}"
    local manifest="${sandbox_dir}/manifest.json"
    local os_name

    if [[ ! -f "$manifest" ]]; then
        os_name="$(mint_openshell_name "$(dirname "$sandbox_dir")")" || return 1
        mkdir -p "$sandbox_dir"
        jq -n \
            --arg name "$sandbox_name" \
            --arg os_name "$os_name" \
            --arg created "$(date -u +"%Y-%m-%dT%H:%M:%SZ")" \
            '{name: $name, openshell_name: $os_name, created: $created, repos: {}}' \
            > "${manifest}.tmp"
        mv "${manifest}.tmp" "$manifest"
    fi

    if [[ -n "$profile" ]]; then
        jq --arg profile "$profile" '.profile = $profile' \
            "$manifest" > "${manifest}.tmp"
        mv "${manifest}.tmp" "$manifest"
    fi

    # Which agent this sandbox launches by default. The manifest is the ONLY
    # store: it lives on the host, so it survives --recreate (which deletes the
    # remote sandbox, never ~/sandboxes/<name>) and host tooling can read it
    # without entering the container. A sandbox cannot write it back — gotcha 6
    # — so a harness picked at the wrapper's prompt is a one-off, and --harness
    # is what changes the memory.
    #
    # Unlike .profile this IS defaulted from the manifest on later commands.
    # Gotcha 5 requires --profile every time because the profile decides which
    # credentials leave the host; the harness decides nothing of the sort — on
    # work both agents' credentials ship regardless.
    if [[ -n "$harness" ]]; then
        jq --arg harness "$harness" '.harness = $harness' \
            "$manifest" > "${manifest}.tmp"
        mv "${manifest}.tmp" "$manifest"
    fi
}

# The remembered harness for a sandbox directory, empty when unset.
manifest_harness() {
    jq -r '.harness // ""' "${1}/manifest.json" 2>/dev/null || true
}

# The `--ensure` command that reopens an existing sandbox dir, built from its
# manifest's name and repos. The profile is the caller's: scode passes the one
# on its command line, --refresh passes the manifest's. No --source-dir — the
# manifest does not keep it, and it only matters on --add-repo.
manifest_ensure_cmd() {
    local sandbox_sh="$1" dir="$2" profile="${3:-}" manifest="${2}/manifest.json" cmd repo_url repo_ref
    printf -v cmd '%s --ensure %q' "$sandbox_sh" "$(jq -r '.name' "$manifest")"
    [[ -n "$profile" ]] && cmd+=" --profile ${profile}"
    while IFS=$'\t' read -r repo_url repo_ref; do
        # The files dir (sandbox.sh FILES_DIR) gets an entry from its stamps, no url.
        [[ -n "$repo_url" ]] || continue
        cmd+=" --repo ${repo_url}"
        [[ -n "$repo_ref" ]] && printf -v cmd '%s --ref %q' "$cmd" "$repo_ref"
    done < <(jq -r '.repos[] | [.url, (.ref // "")] | @tsv' "$manifest")
    printf '%s\n' "$cmd"
}

# VS Code tasks that run CMD (a sandbox.sh --ensure) and a host shell when the
# folder opens. Overwrites; scode only calls it when the file is missing.
write_tasks_json() {
    local dir="$1" cmd="$2"
    mkdir -p "${dir}/.vscode"
    jq -n --arg cmd "$cmd" '
        def task($label; $command): {label: $label, type: "shell", command: $command,
            isBackground: true, problemMatcher: [],
            presentation: {reveal: "always", panel: "new", group: "sandbox-dev"},
            runOptions: {runOn: "folderOpen"}};
        {version: "2.0.0", tasks: [task("sandbox"; $cmd), task("bash"; "exec bash -li")]}' \
        > "${dir}/.vscode/tasks.json"
}

# Work deferred off a stopped sandbox: `refresh_pending`, `recreate_pending`.
# claude-dashboard stops idle sandboxes, and starting one just to refresh or
# recreate it hands it straight back to the dashboard, which stops it again —
# mid-transfer if the next sweep lands first. So --refresh and --recreate --all
# mark the manifest instead, and the next --connect/--ensure runs the work
# before attaching. Host-side, so a session cannot clear its own flag.
manifest_pending() {
    [[ "$(jq -r --arg k "$2" '.[$k] // false' "${1}/manifest.json" 2>/dev/null)" == true ]]
}

set_manifest_pending() {
    local manifest="${1}/manifest.json"
    [[ -f "$manifest" ]] || return 0
    jq --arg k "$2" '.[$k] = true' "$manifest" > "${manifest}.tmp" \
        && mv "${manifest}.tmp" "$manifest"
}

clear_manifest_pending() {
    local manifest="${1}/manifest.json" key
    [[ -f "$manifest" ]] || return 0
    shift
    for key in "$@"; do
        jq --arg k "$key" 'del(.[$k])' "$manifest" > "${manifest}.tmp" \
            && mv "${manifest}.tmp" "$manifest"
    done
}

valid_harness() {
    [[ "$1" == claude || "$1" == codex ]]
}

# Warn and confirm if a personal/home profile is adding a private repo
guard_private_repo() {
    local url="$1"
    if ! personal_profile "${SANDBOX_PROFILE:-}"; then
        return 0
    fi
    if is_private_repo "$url"; then
        local repo_name
        repo_name=$(basename "$url" .git)
        echo "" >&2
        echo "Warning: '${repo_name}' is a private repo — personal sandboxes should only use public repos." >&2
        echo "" >&2
        read -rp "Continue anyway? [y/N]: " confirm
        if [[ "${confirm:-N}" != [yY] ]]; then
            echo "Aborted." >&2
            exit 1
        fi
    fi
}
